     * 암호화된 데이터인지 확인 (Base64 형식인지 검사)
     *
     * @param text 검사할 문자열
     * @return 암호화된 데이터 여부
     */
    public boolean isEncrypted(String text) {
        if (text == null || text.isEmpty()) {
